import{_ as i,c as s,o as e,ag as l}from"./chunks/framework.ymCRTBvy.js";const u=JSON.parse('{"title":"2.4_编写HelloWorld代码","description":"","frontmatter":{},"headers":[],"relativePath":"swift/basics/2.4_编写HelloWorld代码.md","filePath":"swift/basics/2.4_编写HelloWorld代码.md"}'),t={name:"swift/basics/2.4_编写HelloWorld代码.md"};function o(n,a,r,d,p,h){return e(),s("div",null,a[0]||(a[0]=[l(`<h1 id="_2-4-编写helloworld代码" tabindex="-1">2.4_编写HelloWorld代码 <a class="header-anchor" href="#_2-4-编写helloworld代码" aria-label="Permalink to &quot;2.4_编写HelloWorld代码&quot;">​</a></h1><p>编写你的第一个“Hello, World!”程序，开启Swift编程之旅吧！🎉 这是一个激动人心的时刻，你将亲手创建并运行你的第一个Swift程序。别担心，过程非常简单，而且成就感满满！</p><h2 id="创建playground文件" tabindex="-1">创建Playground文件 <a class="header-anchor" href="#创建playground文件" aria-label="Permalink to &quot;创建Playground文件&quot;">​</a></h2><p>首先，打开Xcode。在启动界面，选择“Create a new Xcode project”。在模板选择界面，选择“iOS” -&gt; “Playground”，然后点击“Next”。给你的Playground命名，比如“HelloWorld”，然后选择一个保存位置，点击“Create”。</p><h2 id="编写代码" tabindex="-1">编写代码 <a class="header-anchor" href="#编写代码" aria-label="Permalink to &quot;编写代码&quot;">​</a></h2><p>现在，你将看到一个空白的Playground。在代码编辑区域，输入以下代码：</p><div class="language-swift vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">swift</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">print</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Hello, World!&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>这行代码非常简单：<code>print()</code> 是一个Swift内置函数，用于在控制台输出文本。双引号 <code>&quot; &quot;</code> 之间的 &quot;Hello, World!&quot; 就是你想要输出的内容。</p><h2 id="运行代码" tabindex="-1">运行代码 <a class="header-anchor" href="#运行代码" aria-label="Permalink to &quot;运行代码&quot;">​</a></h2><p>Playground会自动运行你的代码。你会在Xcode窗口底部的控制台区域看到输出结果 &quot;Hello, World!&quot;。如果没有自动运行，你可以点击Playground窗口左下角的播放按钮 ▶️ 来手动运行。</p><h2 id="代码解读" tabindex="-1">代码解读 <a class="header-anchor" href="#代码解读" aria-label="Permalink to &quot;代码解读&quot;">​</a></h2><ul><li><strong><code>print()</code> 函数</strong>: 这是Swift中用于输出信息到控制台的标准方法。</li><li><strong>字符串</strong>: &quot;Hello, World!&quot; 是一个字符串，也就是一段文本。在Swift中，字符串需要用双引号括起来。</li><li><strong>控制台</strong>: 控制台是Xcode中一个显示程序输出信息的区域。</li></ul><h2 id="恭喜你" tabindex="-1">恭喜你！ <a class="header-anchor" href="#恭喜你" aria-label="Permalink to &quot;恭喜你！&quot;">​</a></h2><p>你已经成功编写并运行了你的第一个Swift程序！🥳 这是一个重要的里程碑。通过这个简单的例子，你了解了如何在Xcode中创建Playground，编写Swift代码，以及运行程序并查看输出结果。</p><p>接下来，你可以尝试修改 &quot;Hello, World!&quot; 中的文本，看看会发生什么。你也可以尝试使用 <code>print()</code> 函数输出其他内容，比如你的名字或者你喜欢的数字。</p><div class="language-swift vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">swift</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">print</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;我的名字是[你的名字]&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">print</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;我最喜欢的数字是[你的数字]&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>通过不断尝试和实践，你会越来越熟悉Swift编程。加油！💪</p>`,17)]))}const k=i(t,[["render",o]]);export{u as __pageData,k as default};
